  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.95
  }
});

Eval.writeReport({
  report,
  format: 'json',
  reportPath: './frai-eval-report.json'
});

if (report.passed === false) {
  process.exit(1); // fail CI if any threshold fails
}
```

