  it('validates thresholds against metrics', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9,
        toxicity: 0.95
      }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: 1,
      passed: true
    });
    expect(report.thresholds[1]).toEqual({
      metric: 'toxicity',
      min: 0.95,
      score: 1,
      passed: true
    });
  });

  it('fails thresholds when score is too low', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: 0.5,
      passed: false
    });
  });

  it('fails thresholds when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: null,
      passed: false
    });
  });
});

